'use client';

import React from 'react';
import { Sparkles } from './sparkles-title-sparkles';

interface SparklesTitleProps {
  title?: React.ReactNode;
  children?: React.ReactNode;
}

function SparklesTitle({
  title = 'UI-LAYOUTS',
  children = 'It is a modern and minimalist UI component library designed to simplify the process of building responsive and visually appealing web interfaces.',
}: SparklesTitleProps) {
  return (
    <>
      <div className='min-h-screen w-full overflow-hidden bg-black'>
        <div className='relative  h-80 w-full overflow-hidden mask-[radial-gradient(50%_50%,white,transparent)] before:absolute before:inset-0 before:bg-[radial-gradient(circle_at_bottom_center,#369eff,transparent_90%)] before:opacity-100  after:absolute after:border-2 after:-left-1/2 after:top-1/2 after:aspect-[1/1.8] after:w-[200%] after:rounded-[50%] after:border-b after:border-[#7876c566] after:bg-zinc-900'>
          <div className='absolute bottom-0 left-0 right-0 top-0 bg-[linear-gradient(to_right,#ffffff2c_1px,transparent_1px),linear-gradient(to_bottom,#3a3a3a01_1px,transparent_1px)] bg-size-[70px_80px] '></div>
          <Sparkles
            density={400}
            size={1.4}
            direction='top'
            className='absolute inset-x-0 top-0 h-full w-full mask-[radial-gradient(50%_50%,white,transparent_85%)]'
          />
        </div>
        <div className='mx-auto -mt-52  w-full max-w-2xl relative z-10'>
          <div className='bg-white backdrop-blur-lg border border-neutral-800 p-4  w-28 h-28 mx-auto grid place-content-center rounded-full'>
            <div className=' w-12 h-12 translate-x-1 translate-y-1 mx-auto bg-black rounded-lg before:absolute relative before:w-full before:h-full before:bg-black/50 before:rounded-lg before:-top-2 before:-left-2'></div>
          </div>
        </div>
        <article className='text-white  pt-2 w-2/3 mx-auto block text-center z-10 relative '>
          <h1 className='text-center text-5xl text-white font-medium py-3'>
            {title}
          </h1>
          {children}
        </article>
      </div>
    </>
  );
}

export { SparklesTitle };
export default SparklesTitle;

'use client';
/* eslint-disable @typescript-eslint/no-explicit-any */

import { useId } from 'react';
import type { Engine, ISourceOptions } from '@tsparticles/engine';
import Particles, { ParticlesProvider } from '@tsparticles/react';
import { loadSlim } from '@tsparticles/slim';

// @tsparticles/react v4 replaced initParticlesEngine with a provider whose
// init callback must stay stable, so it lives at module scope.
const initEngine = async (engine: Engine) => {
  await loadSlim(engine);
};

interface SparklesProps {
  className?: string;
  size?: number;
  minSize?: number | null;
  density?: number;
  speed?: number;
  minSpeed?: number | null;
  opacity?: number;
  direction?: string;
  opacitySpeed?: number;
  minOpacity?: number | null;
  color?: string;
  mousemove?: boolean;
  hover?: boolean;
  background?: string;
  options?: Record<string, any>; // Adjust type as needed based on `options` structure
}

export function Sparkles({
  className,
  size = 1.2,
  minSize = null,
  density = 800,
  speed = 1.5,
  minSpeed = null,
  opacity = 1,
  direction = '',
  opacitySpeed = 3,
  minOpacity = null,
  color = '#ffffff',
  mousemove = false,
  hover = false,
  background = 'transparent',
  options = {},
}: SparklesProps) {
  const id = useId();
  const defaultOptions = {
    background: {
      color: {
        value: background,
      },
    },
    fullScreen: {
      enable: false,
      zIndex: 1,
    },
    fpsLimit: 300,

    interactivity: {
      events: {
        onClick: {
          enable: true,
          mode: 'push',
        },
        onHover: {
          enable: hover,
          mode: 'grab',
          parallax: {
            enable: mousemove,
            force: 60,
            smooth: 10,
          },
        },
        resize: true as any,
      },
      modes: {
        push: {
          quantity: 4,
        },
        repulse: {
          distance: 200,
          duration: 0.4,
        },
      },
    },
    particles: {
      color: {
        value: color,
      },
      move: {
        enable: true,
        direction,
        speed: {
          min: minSpeed || speed / 130,
          max: speed,
        },
        straight: true,
      },
      collisions: {
        absorb: {
          speed: 2,
        },
        bounce: {
          horizontal: {
            value: 1,
          },
          vertical: {
            value: 1,
          },
        },
        enable: false,
        maxSpeed: 50,
        mode: 'bounce',
        overlap: {
          enable: true,
          retries: 0,
        },
      },
      number: {
        value: density,
      },
      opacity: {
        value: {
          min: minOpacity || opacity / 10,
          max: opacity,
        },
        animation: {
          enable: true,
          sync: false,
          speed: opacitySpeed,
        },
      },
      size: {
        value: {
          min: minSize || size / 1.5,
          max: size,
        },
      },
    },
    detectRetina: true,
  };
  return (
    <ParticlesProvider init={initEngine}>
      <Particles
        id={id}
        options={{ ...defaultOptions, ...options } as unknown as ISourceOptions}
        className={className}
      />
    </ParticlesProvider>
  );
}
